using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Match Result PREFAB (Assets/_Project/Prefabs/UI/MatchResult.prefab,
/// UIPrefabLibrarySO.matchResult, generated by Tools > MusicGame > UI > Build All UI Prefabs) — ONE
/// configurable view for BOTH Win and Lose (see MatchResultController's own doc on why this isn't two
/// parallel screens): a big title (the MATCH outcome), ONE results list (nested EvaluationPanel prefab)
/// with three labelled sections — FIGHT (result, stars, rounds, metrics), RACE (the preceding run, stars),
/// MATCH (combined stars + effect on the campaign level) — Win-only Continue/Select Song buttons,
/// Lose-only Fight Again/Replay Song buttons and a small Rewarded-Ad confirmation sub-panel. Static labels carry a LocalizedText; the controller only fills data-dependent texts.
/// </summary>
public class MatchResultView : MonoBehaviour
{
    public GameObject      root;
    public TextMeshProUGUI titleText;
    [Tooltip("PERFECT! — won without the health bar ever losing anything (shown + animated by MatchResultController).")]
    public TextMeshProUGUI perfectBanner;

    [Header("Win only")]
    public Button          continueButton;
    public TextMeshProUGUI continueButtonLabel;
    public Button          selectSongButton;
    public TextMeshProUGUI selectSongButtonLabel;

    [Header("Lose only")]
    public Button          fightAgainButton;
    public TextMeshProUGUI fightAgainButtonLabel;
    public Button          replaySongButton;
    public TextMeshProUGUI replaySongButtonLabel;

    [Header("Both")]
    public Button          mainMenuButton;
    public TextMeshProUGUI mainMenuButtonLabel;
    [Tooltip("The ONE results list: FIGHT / RACE / MATCH sections (nested EvaluationPanel prefab).")]
    public EvaluationPanel evaluationPanel;

    [Header("Rewarded Ad confirmation (Lose, no lives)")]
    public GameObject      rewardAdModalRoot;
    public TextMeshProUGUI rewardAdTitleText;
    public Button          watchAdButton;
    public TextMeshProUGUI watchAdButtonLabel;
    public Button          cancelButton;
    public TextMeshProUGUI cancelButtonLabel;
}
